create table if not exists public.seo_landing_pages (slug text primary key check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), content jsonb not null default '{}', cover_url text not null default '', tour_slugs text[] not null default '{}', published boolean not null default false, updated_at timestamptz not null default now());
alter table public.seo_landing_pages enable row level security;
drop policy if exists landing_read on public.seo_landing_pages;
create policy landing_read on public.seo_landing_pages for select to anon,authenticated using (published or (select public.is_site_admin()));
drop policy if exists landing_admin on public.seo_landing_pages;
create policy landing_admin on public.seo_landing_pages for all to authenticated using ((select public.is_site_admin())) with check ((select public.is_site_admin()));
grant select on public.seo_landing_pages to anon,authenticated;
grant insert,update,delete on public.seo_landing_pages to authenticated;
insert into public.seo_landing_pages(slug,content) values ('tours-from-batumi','{"en": {"title": "Private Tours from Batumi", "body": "Explore Adjara’s waterfalls, mountain villages and Black Sea landscapes on a private trip from Batumi. Choose a route that suits your group and ask about pickup, travel time and seasonal road conditions.", "description": "Explore Adjara’s waterfalls, mountain villages and Black Sea landscapes on a private trip from Batumi. Choose a route that suits your group and ask about p", "seo_title": "Private Tours from Batumi", "faq": []}}'::jsonb) on conflict do nothing;
